def minPath(grid, k):
    N = len(grid)
    # Find the cell with value 1
    start = None
    for i in range(N):
        for j in range(N):
            if grid[i][j] == 1:
                start = (i, j)
                break
        if start:
            break

    result = [1]
    r, c = start

    for _ in range(k - 1):
        # Try to move to the smallest possible neighbor
        neighbors = []
        if r > 0:
            neighbors.append((r - 1, c, grid[r - 1][c]))
        if r < N - 1:
            neighbors.append((r + 1, c, grid[r + 1][c]))
        if c > 0:
            neighbors.append((r, c - 1, grid[r][c - 1]))
        if c < N - 1:
            neighbors.append((r, c + 1, grid[r][c + 1]))

        # Sort by value, pick the smallest
        neighbors.sort(key=lambda x: x[2])
        nr, nc, nv = neighbors[0]
        result.append(nv)
        r, c = nr, nc

    return result
