def minPath(grid, k):
    N = len(grid)
    # Find the minimum value and its position
    min_val = min(min(row) for row in grid)

    # Find position of min_val
    start_r, start_c = -1, -1
    for i in range(N):
        for j in range(N):
            if grid[i][j] == min_val:
                start_r, start_c = i, j
                break
        if start_r != -1:
            break

    if k == 1:
        return [min_val]

    # Greedy: at each step, pick the smallest neighbor
    path = [min_val]
    r, c = start_r, start_c

    for _ in range(k - 1):
        best_val = float('inf')
        best_pos = None
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < N and 0 <= nc < N:
                val = grid[nr][nc]
                if val < best_val:
                    best_val = val
                    best_pos = (nr, nc)

        if best_pos is None:
            break

        path.append(best_val)
        r, c = best_pos

    return path
```

