def is_multiply_prime(a):
    """Write a function that returns true if the given number is the multiplication of 3 prime numbers
    and false otherwise.
    Knowing that (a) is less then 100. 
    Example:
    is_multiply_prime(30) == True
    30 = 2 * 3 * 5
    """
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    # Try all combinations of 3 primes whose product equals a
    # Since a < 100, the primes are small
    for p1 in range(2, a):
        if not is_prime(p1):
            continue
        if a % p1 != 0:
            continue
        rest = a // p1
        for p2 in range(p1, rest):
            if not is_prime(p2):
                continue
            if rest % p2 != 0:
                continue
            p3 = rest // p2
            if p3 < p2:
                continue
            if is_prime(p3):
                return True
    return False
```

